WITH inactive AS MATERIALIZED (SELECT candidate.id FROM unnest($1::integer[]) candidate(id) WHERE NOT EXISTS(SELECT 1 FROM (SELECT * FROM public.record WHERE record_eligible) record WHERE record.id_user=candidate.id AND record.date_created>=statement_timestamp()-interval '6 months') OR EXISTS(SELECT 1 FROM public."user" u WHERE u.id=candidate.id AND u.banned)) UPDATE public.user_point_contribution contribution SET player_decayed_points=0,date_calculated=clock_timestamp() FROM inactive WHERE contribution.id_user=inactive.id AND contribution.player_decayed_points IS DISTINCT FROM 0::real
